import{_ as o,o as r,c as e,ag as a}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年7月22日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-22.md","filePath":"science-log/src/reconstructed/2026-07-22.md"}'),n={name:"science-log/src/reconstructed/2026-07-22.md"};function s(i,t,g,u,l,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="🔬-科学快报-2026年7月22日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月22日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月22日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月22日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-07 检索说明：2026-07-22 为<strong>周三</strong>。CrossRef 按 <code>from-pub-date=until-pub-date=2026-07-22</code> 检索：Nature（0028-0836）命中 43 条，其中 <code>10.1038/s41586-…</code> 研究论文 10 条（其余为 <code>10.1038/d41586-…</code> 新闻/Briefing，已丢弃）；PNAS（0027-8424）命中 19 条。故科学 5 篇全部取自<strong>当日真实出版</strong>的 Nature 4 篇 + PNAS 1 篇（EuropePMC 逐条核验摘要）。AI 5 篇严格取自 arXiv <code>submittedDate:[202607220000 TO 202607222359]</code> 的 cs.AI 真实条目（本次抓取命中 40 篇）。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-让-alphafold3-当-特异性顾问-contactseek-把碱基编辑器的脱靶压到已知高保真变体之下" tabindex="-1">🧬 让 AlphaFold3 当&quot;特异性顾问&quot;：ContactSeek 把碱基编辑器的脱靶压到已知高保真变体之下 <a class="header-anchor" href="#🧬-让-alphafold3-当-特异性顾问-contactseek-把碱基编辑器的脱靶压到已知高保真变体之下" aria-label="Permalink to &quot;🧬 让 AlphaFold3 当&quot;特异性顾问&quot;：ContactSeek 把碱基编辑器的脱靶压到已知高保真变体之下&quot;">​</a></h3><p><strong>Precise DNA base editing using AlphaFold3-based contact modelling</strong><em>Nature（2026）</em></p><p>碱基编辑器的核心矛盾是活性—特异性权衡：想剪得准就得牺牲效率，而传统定向进化筛选又极耗人力、成功率低。Haowei Meng、Zhixin Lei、Yongchang Yan、Liren Wang 等人提出 <strong>ContactSeek</strong>——一个把 AlphaFold3（AF3）当作&quot;接触概率探针&quot;的 AI 框架。做法是：先用全基因组脱靶测序画出 Cas9-TadA 腺嘌呤碱基编辑器的脱靶图谱，把这些脱靶 DNA 序列喂给 AF3，然后比较 AF3 输出的<strong>接触概率</strong>而非预测三维结构——他们发现前者的分辨力显著更强，能区分 on-target 与 off-target 复合物的差异相互作用。把接触概率与测序信号做相关，ContactSeek 排出&quot;共识接触区&quot;、定位决定特异性的残基；模块化套用到 TadA8e 脱氨酶上同样有效。最佳变体（Cas9 双突变 + TadA8e 突变）在靶向扩增子测序、全基因组脱靶谱、R 环实验与 RNA 测序四重验证下<strong>优于多个已知高保真腺嘌呤碱基编辑器</strong>，并可推广到 Cas12a 碱基编辑器。这意味着&quot;用结构预测模型反过来指导蛋白质工程&quot;从概念验证走向了可复用的流水线。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10794-z" target="_blank" rel="noreferrer">10.1038/s41586-026-10794-z</a></p><h3 id="🪐-褐矮星旁找到一颗约-0-9-木星质量的-外星卫星-系外卫星首次被径向速度法-称重" tabindex="-1">🪐 褐矮星旁找到一颗约 0.9 木星质量的&quot;外星卫星&quot;：系外卫星首次被径向速度法&quot;称重&quot; <a class="header-anchor" href="#🪐-褐矮星旁找到一颗约-0-9-木星质量的-外星卫星-系外卫星首次被径向速度法-称重" aria-label="Permalink to &quot;🪐 褐矮星旁找到一颗约 0.9 木星质量的&quot;外星卫星&quot;：系外卫星首次被径向速度法&quot;称重&quot;&quot;">​</a></h3><p><strong>Planetary-mass exosatellite detected around the substellar companion of a star</strong><em>Nature（2026）</em></p><p>六千多颗系外行星已确认，但<strong>没有一颗系外卫星被确信探测到</strong>——此前候选者都停在争议里。Kevin Hoy、Alice Zurlo、Pablo A. Peña R.、Jana Köhler 等人换了一条路：不去找绕行星的卫星，而是盯住<strong>直接成像得到的褐矮星伴星 CD-35 2722 B</strong>，把当年发现第一颗系外行星的<strong>径向速度法</strong>用到 VLT/CRIRES+ 的红外光谱上。他们在这颗褐矮星的光谱里找到一个周期性信号，最佳拟合模型对应一颗<strong>最小质量约 0.9 木星质量、周期约 170 天</strong>的卫星。这也是首次用该技术在一个褐矮星伴星周围拿到卫星证据。术语上留了个坑：褐矮星伴星的卫星该不该叫&quot;系外月亮&quot;（exomoon）目前没有正式定义，作者因此称之为 exosatellite。它的价值不止于&quot;又一个第一&quot;——它给出了一条可复制的方法链：高分辨率红外光谱 + 径向速度，随着仪器精度提升，同一条路可以直接去追真正的系外月亮。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10751-w" target="_blank" rel="noreferrer">10.1038/s41586-026-10751-w</a></p><h3 id="⚛️-相变点上序参量-形状-在变-光晶格玻色气体里测出高阶累积量的突然变号" tabindex="-1">⚛️ 相变点上序参量&quot;形状&quot;在变：光晶格玻色气体里测出高阶累积量的突然变号 <a class="header-anchor" href="#⚛️-相变点上序参量-形状-在变-光晶格玻色气体里测出高阶累积量的突然变号" aria-label="Permalink to &quot;⚛️ 相变点上序参量&quot;形状&quot;在变：光晶格玻色气体里测出高阶累积量的突然变号&quot;">​</a></h3><p><strong>Non-Gaussian statistics of the order parameter across a phase transition</strong><em>Nature（2026）</em></p><p>临界现象的标准叙述只讲两件事：幂律标度、普适类决定的临界指数。但序参量的<strong>完整概率分布</strong>本身也是临界性质的载体——理论上预期它是非高斯的，实验上几乎无人测过。Maxime Allemand、Géraud Dupuy、Paul Paquiez、Nicolas Dupuis、Adam Rançon、Tommaso Roscilde 在<strong>相互作用光晶格玻色气体</strong>里，用<strong>动量空间的单原子分辨探测</strong>测出了序参量振幅穿越连续相变时的<strong>全概率分布</strong>。做法很漂亮：把测得的分布当作&quot;实验版朗道理论&quot;去反推有效势，结果在超流（有序）相里出现一个非平庸的极小值，并在相变点消失；更关键的是，靠近相变时高阶累积量非零、并且<strong>发生突变式变号</strong>。数值上他们证明均匀体系里这些变号服从临界标度；而经典模型重现不出实验行为，只有<strong>低温量子模型</strong>能对上。这条结果把&quot;序参量统计&quot;从理论附注抬成了探测普适性的直接观测量——它携带的信息比临界指数更多，也更难被平均场式的模型冒充。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10811-1" target="_blank" rel="noreferrer">10.1038/s41586-026-10811-1</a></p><h3 id="☀️-给自组装单分子层加上-电子共振-钙钛矿电池-85°c-满功率追踪-1080-小时几乎不衰减" tabindex="-1">☀️ 给自组装单分子层加上&quot;电子共振&quot;：钙钛矿电池 85°C 满功率追踪 1080 小时几乎不衰减 <a class="header-anchor" href="#☀️-给自组装单分子层加上-电子共振-钙钛矿电池-85°c-满功率追踪-1080-小时几乎不衰减" aria-label="Permalink to &quot;☀️ 给自组装单分子层加上&quot;电子共振&quot;：钙钛矿电池 85°C 满功率追踪 1080 小时几乎不衰减&quot;">​</a></h3><p><strong>Electronic-resonance enhanced molecule for perovskite solar cells</strong><em>Nature（2026）</em></p><p>自组装单分子层（SAM）是钙钛矿电池效率节节攀升的关键界面层：一端锚在透明导电氧化物上、另一端形成界面偶极抽取载流子。问题是锚定基团上的电子密度有限、键强不足，SAM 在运行应力下会<strong>脱附</strong>，长期稳定性因此受限。Xiaoxiao Wu、Wenwen Kou、Zewei Li、Tiankai Zhang 等人设计了一种<strong>给体—受体—给体（D-A-D）共振结构</strong>的 SAM：电子共振把负电荷密度推到受体型锚定基团上，显著强化膦酸—ITO 键，抑制运行中的脱附；同时共振带来的电荷离域又有利于载流子输运——两个目标不必再互相打架。器件数据：0.063 cm² 认证效率 <strong>27.69%</strong>、15.64 cm² 孔径面积认证 <strong>23.63%</strong>；在 85±5°C、最大功率点追踪 <strong>1080 小时</strong>后仍保持初始效率 <strong>93% 以上</strong>，-40°C 到 85°C 之间 720 次热循环后保持 <strong>97% 以上</strong>。这解决的是&quot;效率纪录好看、组件一晒就掉&quot;的老账。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10919-4" target="_blank" rel="noreferrer">10.1038/s41586-026-10919-4</a></p><h3 id="🩸-取栓成功却不见血流恢复-il-6-压住-adamts13-让-vwf-在-拉伸流-里展开成微血栓" tabindex="-1">🩸 取栓成功却不见血流恢复：IL-6 压住 ADAMTS13，让 VWF 在&quot;拉伸流&quot;里展开成微血栓 <a class="header-anchor" href="#🩸-取栓成功却不见血流恢复-il-6-压住-adamts13-让-vwf-在-拉伸流-里展开成微血栓" aria-label="Permalink to &quot;🩸 取栓成功却不见血流恢复：IL-6 压住 ADAMTS13，让 VWF 在&quot;拉伸流&quot;里展开成微血栓&quot;">​</a></h3><p><strong>Mechanisms of von Willebrand factor activation driving no reflow in ischemic stroke</strong><em>PNAS（2026）</em></p><p>大血管闭塞取栓的再通率约 90%，但近一半患者即使血栓取净仍遗留显著残疾——&quot;无复流&quot;（no-reflow）现象。机制一直不清楚。该研究用小鼠短暂缺血模型 + 活体成像，直接看到血小板—血管性血友病因子（VWF）血栓在<strong>灌注改变了的缺血半暗带</strong>微血管里形成。基于活体观察的计算流体力学建模指出：这些血管里血流汇聚使<strong>局部拉伸流增强</strong>，而拉伸流正是让 VWF 多聚体<strong>展开</strong>、暴露 A1 结构域的经典条件。第二层机制更关键：VWF 活性由 ADAMTS13 切割调控，而卒中急性期局部释放的 <strong>IL-6 抑制 ADAMTS13 对 VWF 的切割</strong>，造成促血栓失衡。临床侧对应得上——缺血性卒中患者急性期 IL-6 升高与 VWF 活性升高强相关，VWF 活性最高的患者预后最差；在离体患者血浆中抑制 IL-6 可<strong>恢复 ADAMTS13 活性</strong>。这把&quot;取栓后再灌注损伤&quot;的一部分归因到了一个可药物干预的炎症—蛋白酶轴。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2610397123" target="_blank" rel="noreferrer">10.1073/pnas.2610397123</a></p><hr><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🛡️-高温采样不许降安全感-refusal-gated-decoding-用-贪心探针-守住拒答" tabindex="-1">🛡️ 高温采样不许降安全感：Refusal-Gated Decoding 用&quot;贪心探针&quot;守住拒答 <a class="header-anchor" href="#🛡️-高温采样不许降安全感-refusal-gated-decoding-用-贪心探针-守住拒答" aria-label="Permalink to &quot;🛡️ 高温采样不许降安全感：Refusal-Gated Decoding 用&quot;贪心探针&quot;守住拒答&quot;">​</a></h3><p><strong>Refusal-Gated Decoding: Preserving Refusal Behavior Under High-Temperature Sampling</strong><em>arXiv（2026）</em></p><p>高温采样能提升多样性，但代价是<strong>拒答行为被削弱</strong>——熵一高，模型对有害请求就开始&quot;松口&quot;。现有补救两条路都不好：要么外挂一个独立安全分类器，等于把模型自己的拒答决定换掉；要么对<strong>每一个</strong> prompt 都改输出分布。Phillip Howard、Xin Su、Allen Roush、Manikandan Ravikiran、Runyan Tan、Amir Abdullah 提出 <strong>refusal-gated decoding（RGD）</strong>：先跑一段很短的<strong>贪心探针</strong>（复用 prompt 的 KV cache），一旦探针输出与学到的&quot;拒答前缀集&quot;不兼容就立即退出；兼容则直接返回贪心结果（即保留模型本来的拒答），不兼容则丢弃探针、回到原始 prompt 按<strong>精确的高温分布</strong>采样。七款模型 × 三个基准、T=2.0 下，贪心拒答保持率从直接采样的 <strong>91.9% 提升到 98.3%</strong>，而非拒答请求的中位延迟只增加 <strong>2.2–4.3%</strong>。与&quot;prompt 筛查&quot;类基线相比，RGD 把大量贪心<strong>非拒答</strong>也保住，不会错误地把正常请求降级成贪心。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.20791" target="_blank" rel="noreferrer">2607.20791</a></p><h3 id="🤖-混合专家-vla-自己长出-动作积木-路由学会排程-专家变成可复用原语" tabindex="-1">🤖 混合专家 VLA 自己长出&quot;动作积木&quot;：路由学会排程，专家变成可复用原语 <a class="header-anchor" href="#🤖-混合专家-vla-自己长出-动作积木-路由学会排程-专家变成可复用原语" aria-label="Permalink to &quot;🤖 混合专家 VLA 自己长出&quot;动作积木&quot;：路由学会排程，专家变成可复用原语&quot;">​</a></h3><p><strong>Emergent Compositional Skills in Mixture-of-Experts VLAs</strong><em>arXiv（2026）</em></p><p>问题设定很干净：只用专家示范端到端训练，<strong>不预设任何任务分解或层级</strong>，能不能自己长出组合性？Shlok Shah、Rhiaan Jhaveri、Tharun Kumar Tiruppali Kalidoss、Chirayu Nimonkar、Ishaan Javali、Dhruv Shah 把一个简化的 MoE 动作头接到视觉—语言—动作（VLA）模型上。结果是肯定的一半：学到的专家在任务间被<strong>大量复用</strong>，且稳定对应到<strong>性质上互不相同</strong>的低层行为；MoE 的任务成功率与单体基线<strong>持平</strong>，却额外获得了专家专精。作者的解释是——路由器隐式承担了高层时序排程，专家则充当组合原语。这条实验的意义在于它把&quot;模块化、可解释的机器人策略&quot;从人工设计问题变成了<strong>数据驱动的涌现问题</strong>，而且证明这种涌现不需要牺牲性能。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.20771" target="_blank" rel="noreferrer">2607.20771</a></p><h3 id="🧩-把-叠加-直接塞进架构-paritytransformer-用无参数代数字典替掉每层过度完备瓶颈" tabindex="-1">🧩 把&quot;叠加&quot;直接塞进架构：ParityTransformer 用无参数代数字典替掉每层过度完备瓶颈 <a class="header-anchor" href="#🧩-把-叠加-直接塞进架构-paritytransformer-用无参数代数字典替掉每层过度完备瓶颈" aria-label="Permalink to &quot;🧩 把&quot;叠加&quot;直接塞进架构：ParityTransformer 用无参数代数字典替掉每层过度完备瓶颈&quot;">​</a></h3><p><strong>Scaling Interpretable Transformers with Parity Bottleneck Layers</strong><em>arXiv（2026）</em></p><p>语言模型在残差流里用远多于维度的特征做<strong>叠加表示</strong>，事后靠稀疏自编码器（SAE）去捞特征；但&quot;天生可解释&quot;的模型一直不实用，因为每层都放一个过度完备瓶颈，显存和算力都吃不消。Andrew Mack、Kraig Yuheng Tou、Mark Henry、Zhengxun Wu、Lauren Greenspan 给出 <strong>ParityTransformer</strong>：每层用 <strong>Deep Parity Bottleneck（DPB）<strong>把可学习的过度完备基换成</strong>无参数的代数字典</strong>，从而拿到确定性的非相干性保证（deterministic incoherence guarantee），并消掉规模化瓶颈的显存开销。DPB 是分层结构的稀疏瓶颈，用<strong>多级 MoE</strong> 高效强制稀疏，硬件感知实现把&quot;激活稀疏训练 vs 稠密训练&quot;的成本差压到可接受的&quot;可解释性税&quot;。实测在稀疏探测任务上不劣于事后 SAE，在特征吸收、steering 有效性、细粒度因果干预上<strong>更优</strong>。关键结构优势：后续计算只作用在通过瓶颈的特征上，所以这些特征是模型前向过程<strong>原生的</strong>，不是事后重构的近似。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.20652" target="_blank" rel="noreferrer">2607.20652</a></p><h3 id="📐-softreason-把-立即推论算子-变成可微的-让感知与演绎之间不再有断点" tabindex="-1">📐 SoftReason：把&quot;立即推论算子&quot;变成可微的，让感知与演绎之间不再有断点 <a class="header-anchor" href="#📐-softreason-把-立即推论算子-变成可微的-让感知与演绎之间不再有断点" aria-label="Permalink to &quot;📐 SoftReason：把&quot;立即推论算子&quot;变成可微的，让感知与演绎之间不再有断点&quot;">​</a></h3><p><strong>SoftReason: A Fully Differentiable Neuro-Soft-Symbolic Deductive Reasoning Architecture over High-Dimensional Perceptual Data</strong><em>arXiv（2026）</em></p><p>很多推理任务的前提根本不是离散符号，得从高维输入里推；而谓词表、论元结构、可信证据往往由知识图谱（KG）或规则定义提供。经典神经—符号流水线在<strong>感知与演绎之间有一个离散接口</strong>，梯度到此断掉。Wael AbdAlmageed 的 <strong>SoftReason</strong> 把演绎状态表示成候选常量与谓词上的<strong>局部软解释张量</strong>：感知模块提出概率化的基础事实，KG 三元组作为高置信软证据注入，查询锚点、谓词选择、闭包更新<strong>全程可微</strong>。核心创新是对<strong>立即推论算子（immediate-consequence operator）<strong>做可学习的可微提升——用谓词定义嵌入与潜在组合通道形成软体谓词混合，对所有可能见证者聚合，提出查询条件化的头事实，再用</strong>单调概率 OR</strong> 更新解释。在知识感知视觉问答（KVQA）上实例化，把端到端感知落地、KG 证据注入与可微演绎闭包统一进一个可训练架构。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.20402" target="_blank" rel="noreferrer">2607.20402</a></p><h3 id="📊-多样性指标测的是多样性还是能力-31-900-个子集的能力受控审计-多数投票几乎不赢最强单体" tabindex="-1">📊 多样性指标测的是多样性还是能力？31,900 个子集的能力受控审计：多数投票几乎不赢最强单体 <a class="header-anchor" href="#📊-多样性指标测的是多样性还是能力-31-900-个子集的能力受控审计-多数投票几乎不赢最强单体" aria-label="Permalink to &quot;📊 多样性指标测的是多样性还是能力？31,900 个子集的能力受控审计：多数投票几乎不赢最强单体&quot;">​</a></h3><p><strong>Are Diversity Metrics Measuring Diversity? A Capability-Controlled Audit of Majority-Vote Gain in LLM Ensembles</strong><em>arXiv（2026）</em></p><p>&quot;多模型投票靠多样性获益&quot;是常识，而多样性指标正被用来挑选组合成员。Donghwan Kim 直接审这五个指标到底在测什么：在 MMLU-Pro（30 个 LLM，TruthfulQA 上 29 个）的 <strong>31,900 个子集</strong>上、在显式能力控制下，检验它们对&quot;相对最强单体的多数投票增益&quot;的预测力。三个结论都很扎心。其一，<strong>潜在互补性无处不在但基本抓不住</strong>：oracle 增益在 100% 的子集里为正，而简单投票只在 <strong>9.98%</strong> 的标准 size-3 子集里赢过最强成员（改用留出最优选择为 18.71%，size-2~4 合并仅 1.27%，部分源于偶数规模投票的确定性行为）。其二，一个联合正确性代理（strict diversity）与&quot;1 减平均准确率&quot;几乎共线（size-3 Spearman ρ = +0.991/+0.988）——原始&quot;多样性—增益&quot;关联被<strong>能力严重纠缠</strong>，控制后（除一例外）都不稳定。其三，三个线性列联表统计量<strong>代数上不可分</strong>；能力控制后稳健残留的只有一个很温和的<strong>成对共同失败</strong>关联：共享错误越多，增益越低。幅度则依赖配置。结论很实用：把 strict diversity、disagreement、double-fault 当独立预测子做联合回归，模型<strong>按构造就是秩亏的</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.20768" target="_blank" rel="noreferrer">2607.20768</a></p><blockquote><p>📅 日期：2026-07-22 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',46)])])}const p=o(n,[["render",s]]);export{d as __pageData,p as default};
